def luhn_valid(s):
    s = s.replace(" ", "")
    if len(s) < 2 or not s.isdigit():
        return False
    total = 0
    for i in range(len(s) - 1, -1, -1):
        digit = int(s[i])
        if i % 2 == 0:
            digit *= 2
            if digit > 9:
                digit -= 9
        total += digit
    return total % 10 == 0
```

