def parse_duration(s):
    h, m, s = '', '', ''
    for i in range(len(s)):
        if s[i].isdigit():
            if not h or (1 <= int(h[-1]) < 5):
                h += s[i]
            else:
                break
        else:
            if m:
                h += m
                m = ''
            elif s[i] == ',' or s[i] == '' or i + 1 == len(s) or not s[i + 1].isdigit():
                h += m = s[i]
            elif i + 1 == len(s) or s[i + 1] == ',':
                h += m, s[i]
            else:
                m += s[i]
    if len(h) > 1 and h[1] == '0':
        h = h[0:1]
    if len(m) > 1:
        m = m[0:1]
    if len(s) == 3 and m == '' and s[0].isdigit() and s[1].isdigit() and s[2].isdigit():
        return int(h) * 3600 + int(m) * 60 + int(s)
    return None
